// features/lifecycle.feature: A re-uploaded document is the one that gets reviewed
import { expect, expectStatus, test } from "../../fixtures";
import type { Document, Vendor } from "../../fixtures";

interface QueueExtraction {
  id: string;
  document_id: string;
  kind: string;
  fields: Record<string, { value: string | null; confidence: number }>;
}
interface QueueItem {
  vendor_id: string;
  extractions: QueueExtraction[];
}
interface ListedDocument extends Document {
  created_at: string;
}

test("a re-uploaded W-9 is the one that gets reviewed", { tag: "@LIF-01" }, async ({ factory, apiAs }) => {
  // Arrange: a draft vendor with extracted insurance certificate and contract
  const member = await apiAs("member");
  const vendor = await factory.vendor();
  await factory.upload(vendor.id, "insurance_certificate");
  await factory.upload(vendor.id, "contract");

  // Arrange: first W-9, legal name "First Name LLC", extracted
  const first = await expectStatus<Document>(
    await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "w9",
        file: {
          name: "w9-first.txt",
          mimeType: "text/plain",
          buffer: Buffer.from("Legal Name: First Name LLC\nTax ID: 84-2219067\nBusiness Type: LLC\n"),
        },
      },
    }),
    201,
  );
  await expect
    .poll(
      async () => (await expectStatus<Document>(await member.get(`/api/documents/${first.id}`), 200)).status,
      { message: "first W-9 is extracted", timeout: 30_000 },
    )
    .toBe("extracted");

  // Arrange: second W-9, legal name "Second Name LLC", extracted
  const second = await expectStatus<Document>(
    await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "w9",
        file: {
          name: "w9-second.txt",
          mimeType: "text/plain",
          buffer: Buffer.from("Legal Name: Second Name LLC\nTax ID: 84-2219067\nBusiness Type: LLC\n"),
        },
      },
    }),
    201,
  );
  await expect
    .poll(
      async () =>
        (await expectStatus<Document[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200))
          .map((d) => d.status)
          .sort(),
      { message: "all four documents are extracted", timeout: 30_000 },
    )
    .toEqual(["extracted", "extracted", "extracted", "extracted"]);

  // Act: the member submits and a reviewer opens the review queue
  const submitted = await expectStatus<Vendor>(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
  expect(submitted.status).toBe("in_review");
  const reviewer = await apiAs("reviewer");
  const queue = await expectStatus<QueueItem[]>(await reviewer.get("/api/review-queue"), 200);

  // Assert: the queue's W-9 extraction is the second upload
  const item = queue.find((q) => q.vendor_id === vendor.id);
  expect(item, "vendor appears in the review queue").toBeDefined();
  const w9Extractions = (item?.extractions ?? []).filter((e) => e.kind === "w9");
  expect(w9Extractions, "exactly one W-9 extraction is up for review").toHaveLength(1);
  expect(w9Extractions[0].document_id).toBe(second.id);
  expect(w9Extractions[0].fields.legal_name.value).toBe("Second Name LLC");

  // Assert: the documents list keeps both W-9 uploads, oldest first
  const documents = await expectStatus<ListedDocument[]>(
    await member.get(`/api/vendors/${vendor.id}/documents`),
    200,
  );
  const w9Documents = documents.filter((d) => d.kind === "w9");
  expect(w9Documents.map((d) => d.id)).toEqual([first.id, second.id]);
  expect(Date.parse(w9Documents[0].created_at)).toBeLessThanOrEqual(Date.parse(w9Documents[1].created_at));
});
